var FMT_OPTIONS = [
  { k:'auto',  lbl:'Autoservicios' },
  { k:'bae',   lbl:'BAE' },
  { k:'perec', lbl:'Perecederos' },
  { k:'sams',  lbl:"SAM'S" },
];
